    static byte[] apng(byte[] png)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(png,0,33);out.write(chunk("acTL",java.nio.ByteBuffer.allocate(8).putInt(1).putInt(0).array()));out.write(chunk("fcTL",java.nio.ByteBuffer.allocate(26).putInt(0).putInt(11).putInt(5).putInt(0).putInt(0).putShort((short)1).putShort((short)10).put((byte)0).put((byte)0).array()));out.write(png,33,png.length-33);return out.toByteArray();}
