    static final class MemoryPack implements PackResources {
        final String name;final Map<ResourceLocation,byte[]> bytes=new TreeMap<>();int opens,reads;
        MemoryPack(String name){this.name=name;}
        void put(String id,byte[] value){bytes.put(ResourceLocation.parse(id),value);}
        public String packId(){return name;}
        public PackLocationInfo location(){return new PackLocationInfo(name,net.minecraft.network.chat.Component.literal(name),net.minecraft.server.packs.repository.PackSource.DEFAULT,Optional.empty());}
        public IoSupplier<InputStream> getRootResource(String... path){return null;}
        public IoSupplier<InputStream> getResource(PackType type,ResourceLocation id){byte[] value=bytes.get(id);return value==null?null:()->{opens++;return new ByteArrayInputStream(value){@Override public synchronized int read(byte[] b,int off,int len){int n=super.read(b,off,len);if(n>0)reads+=n;return n;}};};}
        public void listResources(PackType type,String namespace,String path,PackResources.ResourceOutput out){bytes.keySet().stream().filter(id->id.getNamespace().equals(namespace)&&id.getPath().startsWith(path+"/")).forEach(id->out.accept(id,getResource(type,id)));}
        public Set<String> getNamespaces(PackType type){Set<String> out=new TreeSet<>();bytes.keySet().forEach(id->out.add(id.getNamespace()));return out;}
        public <T>T getMetadataSection(MetadataSectionSerializer<T> serializer){return null;}
        public void close(){}
    }
    /** Routes namespaces only; all pack precedence and filtering stays in the public manager. */
    static final class PublicResources implements ResourceManager {
        final Map<ResourceLocation,Resource> fixed=new TreeMap<>();final ResourceManager fixture;
        PublicResources(ResourceManager fixture){this.fixture=fixture;}
        public Set<String> getNamespaces(){return Set.of("minecraft","fixture");}
        public Optional<Resource> getResource(ResourceLocation id){return fixed.containsKey(id)?Optional.of(fixed.get(id)):fixture.getResource(id);}
        public List<Resource> getResourceStack(ResourceLocation id){return fixed.containsKey(id)?List.of(fixed.get(id)):fixture.getResourceStack(id);}
        public Map<ResourceLocation,Resource> listResources(String path,Predicate<ResourceLocation> filter){Map<ResourceLocation,Resource> out=new TreeMap<>(fixture.listResources(path,filter));fixed.forEach((id,r)->{if(id.getPath().startsWith(path+"/")&&filter.test(id))out.put(id,r);});return out;}
        public Map<ResourceLocation,List<Resource>> listResourceStacks(String path,Predicate<ResourceLocation> filter){Map<ResourceLocation,List<Resource>> out=new TreeMap<>(fixture.listResourceStacks(path,filter));fixed.forEach((id,r)->{if(id.getPath().startsWith(path+"/")&&filter.test(id))out.put(id,List.of(r));});return out;}
        public Stream<PackResources> listPacks(){return fixture.listPacks();}
    }
